from pathlib import Path
import py_compile

ROOT = Path.cwd()
SUB = ROOT / "qseries_v2/oracle_strategy_intelligence/solana_money/qarb_clean_bot"
QSB = ROOT / "qseries_v2/oracle_strategy_intelligence/solana_money/qsb059_gav_reverse_atomic.py"
Q23 = SUB / "qarb_023b_v0_alt_atomic_packet_compaction.py"

if not QSB.is_file():
    raise SystemExit("[FAIL] exact Python atomic source missing: " + str(QSB))
if not Q23.is_file():
    raise SystemExit("[FAIL] QARB-023B packet gate missing: " + str(Q23))

qsb_src = QSB.read_text(encoding="utf-8", errors="replace")
if "compose_reverse_candidates" not in qsb_src:
    raise SystemExit("[FAIL] QSB exact candidate composer contract missing")

MOD = SUB / "qarb_024_existing_python_atomic_source_bridge.py"
MOD.write_text('from __future__ import annotations\n\nimport importlib\nimport inspect\nfrom dataclasses import dataclass\nfrom typing import Any\n\nfrom qseries_v2.oracle_strategy_intelligence.solana_money.qarb_clean_bot import (\n    qarb_023b_v0_alt_atomic_packet_compaction as packet,\n)\n\nSOURCE_MODULE = (\n    "qseries_v2.oracle_strategy_intelligence.solana_money."\n    "qsb059_gav_reverse_atomic"\n)\nexecution_authority = False\n\n\n@dataclass(frozen=True)\nclass BridgeStatus:\n    source_module: str\n    compose_present: bool\n    packet_gate_present: bool\n    python_only_entry_present: bool\n    execution_authority: bool = False\n\n\ndef load_source():\n    return importlib.import_module(SOURCE_MODULE)\n\n\ndef bridge_status() -> BridgeStatus:\n    qsb = load_source()\n    compose = callable(getattr(qsb, "compose_reverse_candidates", None))\n    packet_gate = callable(getattr(packet, "compile_best_v0", None))\n    python_entry = compose and callable(getattr(qsb, "run", None))\n    return BridgeStatus(\n        source_module=SOURCE_MODULE,\n        compose_present=compose,\n        packet_gate_present=packet_gate,\n        python_only_entry_present=python_entry,\n    )\n\n\ndef compose_exact_candidates(user: Any, token: Any, pump_pool: Any,\n                             meteora_pool: Any, start_sol: float) -> Any:\n    qsb = load_source()\n    fn = getattr(qsb, "compose_reverse_candidates", None)\n    if not callable(fn):\n        raise RuntimeError("EXACT_QSB_ATOMIC_COMPOSER_MISSING")\n    return fn(user, token, pump_pool, meteora_pool, float(start_sol))\n\n\ndef candidate_instruction_sets(route: Any) -> list[tuple[str, list[Any], list[Any]]]:\n    out: list[tuple[str, list[Any], list[Any]]] = []\n\n    def add(label: str, obj: Any):\n        if not isinstance(obj, dict):\n            return\n        ixs = obj.get("instructions")\n        if not isinstance(ixs, (list, tuple)) or not ixs:\n            return\n        alts = obj.get("alts") or obj.get("lookup_tables") or []\n        out.append((label, list(ixs), list(alts)))\n\n    if isinstance(route, dict):\n        if isinstance(route.get("candidates"), (list, tuple)):\n            for i, row in enumerate(route["candidates"]):\n                label = (\n                    str(row.get("label") or row.get("name") or f"CANDIDATE_{i}")\n                    if isinstance(row, dict) else f"CANDIDATE_{i}"\n                )\n                add(label, row)\n\n        add(str(route.get("label") or "ROUTE"), route)\n\n        for key in ("FULL", "NO_COMPUTE_MEMO", "WRAP_SWAP_CLOSE", "PUMP_METEORA_ONLY"):\n            val = route.get(key) or route.get(key.lower())\n            add(key, val)\n\n    elif isinstance(route, (list, tuple)):\n        for i, row in enumerate(route):\n            label = (\n                str(row.get("label") or row.get("name") or f"CANDIDATE_{i}")\n                if isinstance(row, dict) else f"CANDIDATE_{i}"\n            )\n            add(label, row)\n\n    seen = set()\n    dedup = []\n    for label, ixs, alts in out:\n        sig = (label, tuple(id(x) for x in ixs), tuple(id(x) for x in alts))\n        if sig in seen:\n            continue\n        seen.add(sig)\n        dedup.append((label, ixs, alts))\n    return dedup\n\n\ndef select_packet_fit(payer: Any, recent_blockhash: Any, route: Any):\n    rows = candidate_instruction_sets(route)\n    if not rows:\n        raise RuntimeError("NO_EXACT_ATOMIC_INSTRUCTION_CANDIDATES")\n\n    results = []\n    for label, ixs, alts in rows:\n        r = packet.compile_best_v0(\n            payer=payer,\n            recent_blockhash=recent_blockhash,\n            instructions=ixs,\n            lookup_tables=alts,\n        )\n        results.append((label, r))\n        if r.ok:\n            return {\n                "ok": True,\n                "label": label,\n                "result": r,\n                "execution_authority": False,\n            }\n\n    best = min(\n        (r for _, r in results if getattr(r, "best", None) is not None),\n        key=lambda x: x.best.size_bytes,\n        default=None,\n    )\n    return {\n        "ok": False,\n        "status": "NO_PACKET_FIT",\n        "best": best,\n        "attempted": results,\n        "execution_authority": False,\n    }\n\n\ndef source_signature() -> str:\n    qsb = load_source()\n    fn = getattr(qsb, "compose_reverse_candidates", None)\n    if not callable(fn):\n        return "MISSING"\n    return str(inspect.signature(fn))\n', encoding="utf-8")

TEST = ROOT / "test_qarb_024_existing_python_atomic_source_bridge.py"
TEST.write_text('import sys\nimport types\nimport unittest\n\nfake_name = (\n    "qseries_v2.oracle_strategy_intelligence.solana_money."\n    "qsb059_gav_reverse_atomic"\n)\nfake = types.ModuleType(fake_name)\n\ndef compose_reverse_candidates(user, token, pump_pool, meteora_pool, start_sol):\n    return {\n        "candidates": [\n            {"label": "FULL", "instructions": [1, 2], "alts": []},\n            {"label": "PUMP_METEORA_ONLY", "instructions": [3, 4], "alts": ["ALT"]},\n        ]\n    }\n\ndef run():\n    return None\n\nfake.compose_reverse_candidates = compose_reverse_candidates\nfake.run = run\nsys.modules[fake_name] = fake\n\nfrom qseries_v2.oracle_strategy_intelligence.solana_money.qarb_clean_bot import (\n    qarb_024_existing_python_atomic_source_bridge as q,\n)\n\n\nclass T(unittest.TestCase):\n    def test_bridge_contract(self):\n        s = q.bridge_status()\n        self.assertTrue(s.compose_present)\n        self.assertTrue(s.packet_gate_present)\n        self.assertFalse(s.execution_authority)\n        print("[PASS] QSB exact composer -> QARB-023B packet gate bridge present")\n\n    def test_candidate_extraction(self):\n        r = compose_reverse_candidates(None, None, None, None, 0.05)\n        rows = q.candidate_instruction_sets(r)\n        self.assertEqual([x[0] for x in rows], ["FULL", "PUMP_METEORA_ONLY"])\n        self.assertEqual(rows[1][2], ["ALT"])\n        print("[PASS] exact candidate instructions + ALT lineage normalized")\n\n    def test_source_signature(self):\n        sig = q.source_signature()\n        self.assertIn("start_sol", sig)\n        print("[PASS] exact upstream compose signature visible")\n\n    def test_execution_false(self):\n        self.assertIs(q.execution_authority, False)\n        print("[PASS] execution_authority=FALSE")\n\n\nif __name__ == "__main__":\n    unittest.main(verbosity=2)\n', encoding="utf-8")

RUN = ROOT / "run_qarb_024_existing_python_atomic_source_bridge.py"
RUN.write_text('from qseries_v2.oracle_strategy_intelligence.solana_money.qarb_clean_bot import qarb_024_existing_python_atomic_source_bridge as q\n\ns = q.bridge_status()\nprint("[QARB-024] EXISTING PYTHON ATOMIC SOURCE BRIDGE")\nprint("[SOURCE]", s.source_module)\nprint("[COMPOSE_PRESENT]", s.compose_present)\nprint("[PACKET_GATE_PRESENT]", s.packet_gate_present)\nprint("[PYTHON_ONLY_ENTRY_PRESENT]", s.python_only_entry_present)\nprint("[SIGNATURE]", q.source_signature())\nprint("[NEXT] physical exact candidate -> V0/ALT compile -> <=1232 gate")\nprint("[MODE] compose bridge only execution_authority=FALSE")\n', encoding="utf-8")

for p in (MOD, TEST, RUN):
    py_compile.compile(str(p), doraise=True)

print("[PASS] QARB-024 existing Python atomic source bridge installed")
print("[SOURCE] qsb059_gav_reverse_atomic.compose_reverse_candidates")
print("[BRIDGE] exact instruction candidates + supplied ALT lineage -> QARB-023B V0 packet gate")
print("[NO_REVIVAL] Node/npm composer remains retired")
print("[NO_SUBMIT] no sendTransaction/broadcast path added")
